/// <summary>
/// CB 797 send PE pricing Data contract class for service <c>METSendPricingMarkupDetailContract</c>
/// </summary>
[DataContractAttribute]
public class METSendPricingMarkupDetailContract
{
    InventTransId            inventTransId;
    MarkupCode               markupCode;
    MarkupCategory           markupCategory;
    METChargesMethod         chargeMethod;
    MarkupValue              markupValue;
    CurrencyCode             currencyCode;
    TaxGroup                 taxGroup;
    TaxItemGroup             taxItemGroup;
    LineNum                  lineNum;

}

